def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    change = v2 - v1
    return {
        "value": change,
        "trace": {
            "old_value_2017": v1,
            "new_value_2018": v2,
            "change": change,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
